import { defineConfig } from 'vite';
import react from '@vitejs/plugin-react';

/**
 * Vite configuration with React plugin integration.
 */
export default defineConfig({
  plugins: [react()],
});

export interface NavItem {
  readonly label: string;
  readonly href: string;
}

export interface CtaGroup {
  readonly primaryText: string;
  readonly primaryHref: string;
  readonly secondaryText: string;
  readonly secondaryHref: string;
}

export interface HeroContent {
  readonly badge: string;
  readonly title: string;
  readonly subtitle: string;
  readonly description: string;
  readonly cta: CtaGroup;
}

export interface FeatureCard {
  readonly title: string;
  readonly description: string;
  readonly highlight: string;
}

export interface PricingPlaceholder {
  readonly title: string;
  readonly description: string;
  readonly note: string;
  readonly ctaText: string;
}

export interface FaqPlaceholder {
  readonly title: string;
  readonly description: string;
  readonly questionPlaceholder: string;
  readonly answerPlaceholder: string;
  readonly note: string;
}

export interface FooterContact {
  readonly label: string;
  readonly value: string;
}

export interface FooterContent {
  readonly text: string;
  readonly contacts: readonly FooterContact[];
}

export interface LandingPageContent {
  readonly productName: string;
  readonly navigation: readonly NavItem[];
  readonly hero: HeroContent;
  readonly secondaryCta: CtaGroup;
  readonly features: readonly FeatureCard[];
  readonly pricing: PricingPlaceholder;
  readonly faq: FaqPlaceholder;
  readonly footer: FooterContent;
}

export const content: LandingPageContent = {
  productName: '糖护管家',
  navigation: [
    { label: '产品功能', href: '#features' },
    { label: '方案价格', href: '#pricing' },
    { label: '常见问题', href: '#faq' },
    { label: '联系我们', href: '#contact' },
  ],
  hero: {
    badge: '专注糖尿病日常管理',
    title: '让血糖管理更清晰，让控糖执行更轻松',
    subtitle: '为糖尿病患者、家属与健康管理团队打造的一站式数字化管理工具',
    description:
      '通过血糖记录、饮食运动追踪、用药提醒与趋势分析，帮助用户建立更稳定、更可持续的控糖习惯。',
    cta: {
      primaryText: '立即申请体验',
      primaryHref: '#contact',
      secondaryText: '查看核心功能',
      secondaryHref: '#features',
    },
  },
  secondaryCta: {
    primaryText: '预约产品演示',
    primaryHref: '#pricing',
    secondaryText: '获取管理方案',
    secondaryHref: '#faq',
  },
  features: [
    {
      title: '血糖数据智能记录',
      description:
        '支持按空腹、餐前、餐后、睡前等场景快速录入血糖数据，自动生成每日与每周变化视图。',
      highlight: '减少手动整理成本，趋势一目了然',
    },
    {
      title: '用药与复测提醒',
      description:
        '可自定义胰岛素、口服药、复测时间与频率，通过提醒机制降低漏服漏测风险。',
      highlight: '帮助建立规律执行习惯',
    },
    {
      title: '饮食与碳水管理',
      description:
        '记录每日饮食结构、主食摄入与加餐情况，辅助用户关注碳水分配与控糖平衡。',
      highlight: '让饮食调整更有依据',
    },
    {
      title: '运动影响追踪',
